// Üretilen dosya: tool/ozgun/uret.py. Edebiyat · Edebî türler, şiir bilgisi, söz sanatları ve anlatım teknikleri (zor).
const ozLiterature4Zor = <(String, String, List<String>, String)>[
  ('Bir romanın \'roman-nehir\' olarak adlandırılmasının nedeni aşağıdakilerden hangisidir?', 'Bir ailenin öyküsünün ciltler boyunca sürmesi', ['Olayların tümüyle bir nehir kıyısında geçmesi', 'Metnin hiç paragraf kullanılmadan yazılması', 'Romanın tek bir gün içinde geçen olayları anlatması'], 'Roman-nehir (roman-fleuve), bir ailenin ya da kişilerin hayatını birden çok ciltte geniş bir zaman dilimi içinde anlatan dizi romandır.'),
  ('Masalın gerçek dışı olaylar içermesine rağmen toplumda uzun süre yaşamasının en önemli nedeni hangisidir?', 'Toplumsal değerleri sembollerle aktarması', ['Olayların bilimsel olarak kanıtlanmış olması', 'Tarihî kişilerin hayatını belgelemesi', 'Yalnız yetişkinlere yönelik yazılmış olması'], 'Masallar iyilik, adalet, sabır gibi değerleri sembolik bir dünyada işler; bu işlev onları kuşaktan kuşağa taşır.'),
  ('Klasik trajedide kahramanın düşüşüne yol açan trajik hataya ya da kusura ne ad verilir?', 'Hamartia', ['Katarsis', 'Koro', 'Epilog'], 'Hamartia, kahramanın kötü sona sürüklenmesine neden olan yanılgı ya da kusurdur.'),
  ('Klasik trajedide kahramanların genellikle soylu sınıftan ya da tanrı ve kahramanlar arasından seçilmesinin nedeni nedir?', 'Yüksek konumdakinin düşüşünün daha etkili olması', ['Halkın soylu kişileri anlatan oyunlara bilet alamaması', 'Trajedinin yalnız saray mensuplarına oynanması', 'Sıradan insanların sahnede konuşmasının yasak olması'], 'Klasik anlayışa göre yüksek konumdaki kahramanın felakete sürüklenmesi seyircide daha derin bir acıma ve korku uyandırır.'),
  ('Bir oyuncunun, sahnedeki diğer kişilerin duymadığı varsayılarak doğrudan seyirciye söylediği kısa söze ne ad verilir?', 'Apart', ['Tirad', 'Diyalog', 'Epilog'], 'Apart, öteki karakterlerin duymadığı kabul edilen, seyirciye yönelik kısa sözdür.'),
  ('Fıkra yazarlarının çoğunlukla güncel ve gündelik konuları seçmesi bu türe hangi özelliği kazandırır?', 'Gündeme bağlı ve kısa ömürlü olmayı', ['Bilimsel bir kesinlik kazanmayı', 'Masal gibi zamandan bağımsız olmayı', 'Bir tarih belgesi değeri taşımayı'], 'Güncel konular üzerine yazılan fıkralar, gündem değiştiğinde güncelliğini yitirebilir; bu, türün dönemsel niteliğini gösterir.'),
  ('\'Fıkra\' teriminin edebiyatta iki farklı anlamda kullanılması göz önüne alındığında, aşağıdakilerden hangisi gazete fıkrasının değil, halk fıkrasının özelliğidir?', 'Nükteli bir olayın kısaca anlatılması', ['Güncel bir konuda kişisel görüş bildirilmesi', 'Gazetede belli bir köşede yayımlanması', 'Yazarın adının yazıyla birlikte verilmesi'], 'Halk fıkrası, Nasreddin Hoca fıkraları gibi kısa, nükteli ve güldürücü anlatılardır. Diğer seçenekler köşe yazısı anlamındaki fıkraya aittir.'),
  ('Sohbet türü ile deneme arasındaki farkı en iyi açıklayan seçenek hangisidir?', 'Sohbet okurla, deneme yazarın kendisiyle konuşması gibidir', ['Deneme yalnız şiirle, sohbet yalnız düz yazıyla yazılır', 'Sohbette kesin kanıtlar sunulur, denemede kanıt yasaktır', 'Deneme gazetede, sohbet yalnız kitapta yayımlanır'], 'İki tür de samimi ve kişiseldir; sohbetin ayırt edici yanı okura yönelik söyleşi havası, denemeninki ise yazarın iç konuşmasıdır.'),
  ('Bir eleştirmenin bir romanı yazarın hayatı, dönemi ve toplumsal çevresiyle ilişkilendirerek değerlendirmesi hangi eleştiri yaklaşımına örnektir?', 'Sosyolojik ya da tarihsel eleştiri', ['İzlenimci (kişisel beğeniye dayalı) eleştiri', 'Biçimci eleştiri', 'Yapısalcı eleştiri'], 'Eseri ortaya çıktığı toplum, dönem ve koşullarla birlikte açıklayan yaklaşım sosyolojik/tarihsel eleştiridir.'),
  ('Bir eleştirmen bir şiiri yalnızca dil, ses, imge ve yapı özellikleri açısından inceliyor; şairin hayatına ve dönemine hiç değinmiyor. Bu yaklaşım hangi eleştiri anlayışına daha yakındır?', 'Biçimci eleştiri', ['Biyografik eleştiri', 'Sosyolojik eleştiri', 'Psikanalitik eleştiri'], 'Metni kendi iç yapısı ve dil özellikleriyle inceleyen, dış etkenleri dışarıda bırakan yaklaşım biçimci eleştiridir.'),
  ('Anıların tarihçiler için de değerli bir kaynak olarak görülmesinin temel nedeni nedir?', 'Dönemin olaylarına tanıklık etmeleri', ['Olayların tamamen nesnel ve hatasız aktarılması', 'Bilimsel yöntemlerle denetlenmiş olmaları', 'Yazarın hiçbir duygusunu yansıtmaması'], 'Anılar dönemin tanıklığını sunar; ancak öznel oldukları ve hafızaya dayandıkları için başka kaynaklarla karşılaştırılmaları gerekir.'),
  ('Otobiyografi ile anı türleri karşılaştırıldığında hangisi doğrudur?', 'Otobiyografi yazara odaklanır; anıda çevre de öne çıkar', ['İkisi de yalnızca başkalarının hayatını anlatır', 'Anı kurmaca, otobiyografi tamamen bilimsel bir türdür', 'Otobiyografi kısa, anı ise mutlaka çok ciltli olur'], 'Otobiyografinin odağı yazarın kendisidir; anılarda ise yazarın çevresi, dönem ve tanık olunan olaylar da geniş yer tutar.'),
  ('Röportajı mülakattan ayıran temel özellik hangisidir?', 'Gözlem ve izlenimin görüşmeyle birleştirilmesi', ['Röportajda hiç soru sorulmaz, yalnız tanım yapılır', 'Mülakat yalnız şiir, röportaj yalnız tiyatro üzerine yapılır', 'Röportaj kurmaca, mülakat tamamen hayalî bir türdür'], 'Röportaj yerinde gözleme, incelemeye ve farklı kişilerle görüşmelere dayanır; yazarın izlenimleri de metne yansır. Mülakat ise asıl olarak soru-cevaba dayanır.'),
  ('Açık oturumu panelden ayıran en belirgin özellik hangisidir?', 'Dinleyicinin tartışmaya katılmaması', ['Bir başkanın bulunmaması', 'Konunun önceden belirlenmemesi', 'Konuşmacıların uzman olmaması'], 'Açık oturum çoğunlukla radyo ya da televizyonda yapılır ve dinleyiciler konuşmaya katılmaz; panelde ise sonunda soru sorulabilir.'),
  ('Hece ölçüsünde durak yerinin bir sözcüğü ikiye bölmesi için ne denir?', 'Durak kayması', ['İmale', 'Med', 'Ulama'], 'Durağın bir sözcüğün ortasına denk gelmesi kusur sayılır ve durak kayması olarak adlandırılır.'),
  ('11\'li hece ölçüsünün en yaygın durak biçimleri hangileridir?', '6+5 ve 4+4+3', ['5+6 ve 3+8', '7+4 ve 2+9', '8+3 ve 1+10'], '11\'li kalıbın en yaygın durakları 6+5 ve 4+4+3\'tür.'),
  ('Şiir okunurken ünsüzle biten bir sözcüğün son sesinin, ardından gelen ünlüyle başlayan sözcüğe bağlanarak söylenmesine ne ad verilir?', 'Ulama', ['İmale', 'Zihaf', 'Durak'], 'Bu bağlanarak okuma ulamadır (örneğin \'gel ey\' sözünün \'ge-ley\' gibi okunması). Ulama okuyuşu akıcılaştırır ama hece ölçüsündeki hece sayısını değiştirmez.'),
  ('Aruzda kapalı bir hecenin bir buçuk hece değerinde okunmasına, yani bir kapalı ve yarım açık hece gibi sayılmasına ne denir?', 'Med', ['Zihaf', 'İmale', 'Ulama'], 'Med, özellikle uzun ünlü ya da iki ünsüzle biten hecelerin bir buçuk hece değerinde okunmasıdır.'),
  ('Aruz ölçüsünün Türkçeye uygulanmasında yaşanan güçlüğün temel nedeni nedir?', 'Türkçede doğal uzun ünlülerin bulunmaması', ['Türkçe sözcüklerin çoğunun tek heceli olması', 'Türkçede hiç ünsüzle biten hece bulunmaması', 'Türkçenin yazıya geçirilmemiş bir dil olması'], 'Arapça ve Farsçada uzun ünlüler vardır; Türkçede bulunmadığı için Türkçe sözcüklerde imale ve zihaf gibi kusurlar ortaya çıkar.'),
  ('Aruz kalıplarında yer alan \'Fâilâtün, Mefâîlün, Müstef\'ilün\' gibi birimlere ne ad verilir?', 'Tef\'ile (cüz)', ['Durak (nefes yeri)', 'Nakarat', 'Kafiye'], 'Aruz kalıpları tef\'ile adı verilen ölçü birimlerinin dizilmesiyle oluşur.'),
  ('Bir dizenin vezninin bulunması için hecelerin açık ve kapalı olarak işaretlenip kalıba yerleştirilmesi işlemine ne denir?', 'Takti', ['Ulama', 'Kafiye', 'Tekrir'], 'Takti, dizenin hecelerini açık-kapalı olarak ayırıp aruz kalıbını belirleme işlemidir.'),
  ('Bir dörtlükte dize sonları \'yaz\' (mevsim) ve \'yaz\' (yazmak eyleminin emir kipi) sözcükleriyle bitiyor. Bu durum için aşağıdakilerden hangisi doğrudur?', 'Sözcükler sesteş olduğu için cinaslı kafiye oluşur', ['Sözcükler aynı olduğundan redif oluşur', 'Aynı sözcük tekrarlandığı için kafiye oluşmaz', 'Yalnızca tek ses ortak olduğu için yarım kafiye oluşur'], 'Sözcüklerin yazılışı aynı ama anlamları farklı olduğundan bu bir kafiyedir, türü cinaslıdır. Redif aynı anlam ve görevde olmayı gerektirir.'),
  ('\'Yollarda / Kollarda\' kafiyelenmesinde redif ve kafiye hangi seçenekte doğru ayrılmıştır?', 'Redif: -larda, Kafiye: ol', ['Redif: -da, Kafiye: yollar', 'Redif: -lar, Kafiye: arda', 'Redif: -olla, Kafiye: rda'], 'Çokluk eki \'-lar\' ve bulunma eki \'-da\' her iki sözcükte aynı görevdedir; bu yüzden \'-larda\' rediftir. Kalan \'ol\' sesleri tam kafiyedir.'),
  ('Redif ve kafiye bulunurken neden önce redif ayrılır?', 'Kafiye, redifin önündeki ses benzerliği olduğu için', ['Redif her zaman dizenin başında yer aldığı için', 'Kafiye yalnızca sözcük köklerinde aranmadığı için', 'Redifler kafiye türünü her zaman zengin yaptığı için'], 'Kural gereği dize sonundaki aynı görevli ekler ve sözcükler (redif) ayrıldıktan sonra kalan ses benzerliği kafiyedir.'),
  ('\'Gözlerim / Sözlerim\' dize sonlarında kafiye türü hangisidir?', 'Tam kafiye', ['Yarım kafiye', 'Zengin kafiye', 'Cinaslı kafiye'], '\'-ler\' çokluk eki ve \'-im\' iyelik eki aynı görevde olduğu için \'-lerim\' rediftir. Geriye kalan \'öz\' iki ses benzerliğiyle tam kafiyedir.'),
  ('Bir şiirde dize sonlarında yalnızca aynı görevli çekim ekleri tekrarlanıyor, öncesinde başka bir ses benzerliği bulunmuyorsa bu dizeler için ne söylenebilir?', 'Redif vardır, kafiye yoktur', ['Hem kafiye hem redif vardır', 'Yalnızca zengin kafiye vardır', 'Cinaslı kafiye vardır'], 'Kafiye, redif ayrıldıktan sonra kalan ses benzerliğidir; benzerlik yoksa yalnız redif bulunur.'),
  ('Bir dörtlüğün dize sonları \'yol / gönül / dal / bülbül\' şeklindedir. Bu dörtlüğün kafiye şeması hangisidir?', 'abab', ['abba', 'aabb', 'aaab'], 'Birinci \'yol\' ile üçüncü \'dal\' yalnız \'l\' sesiyle, ikinci \'gönül\' ile dördüncü \'bülbül\' \'ül\' sesleriyle kafiyelidir; düzen abab olur.'),
  ('Dize sonları \'bahar / yıl / il / ağar\' olan dörtlüğün kafiye şeması nedir?', 'abba', ['abab', 'aabb', 'aaba'], '1. ve 4. dize (\'bahar-ağar\'), 2. ve 3. dize (\'yıl-il\') kafiyelidir; düzen sarma (abba) olur.'),
  ('aabb biçiminde, dizelerin ikişer ikişer kafiyelendiği düzen Batı şiirinde de yaygındır. Bu düzen en çok hangi nazım biriminin yapısına benzer?', 'Art arda kafiyeli beyitlerin', ['Örüşük üçlüklerin', 'Sarma kafiyeli dörtlüklerin art arda dizilişinin', 'Kafiyesiz serbest bentlerin'], 'aabb düzeninde her iki dize kendi içinde kafiyelidir; bu, kafiyeli beyitlerin art arda dizilmesine benzer.'),
  ('Pastoral şiirin iki türü olan idil ile eglog arasındaki fark nedir?', 'İdil betimler, eglog çobanları konuşturur', ['İdil savaşları, eglog aşkı anlatır', 'İdil serbest ölçüyle, eglog yalnız aruzla yazılır', 'İdil kısa, eglog ise en az yüz dizeden oluşur'], 'İdil kır hayatını betimleyen pastoral şiirdir; eglog ise çobanların karşılıklı konuşması biçiminde yazılır.'),
  ('Batı edebiyatında yüce bir kişiyi, kavramı ya da değeri coşkulu bir dille öven lirik şiir türüne ne ad verilir?', 'Od', ['Eglog', 'Satir', 'Balad'], 'Od, coşkulu övgü içeren lirik şiir türüdür.'),
  ('İngiliz edebiyatında yaygın olan Shakespeare tipi sonenin yapısı hangisidir?', 'Üç dörtlük ve bir beyit', ['İki dörtlük ve iki üçlük', 'Dört üçlük ve iki dize', 'Yedi beyit'], 'Shakespeare sonesi 14 dizedir ancak üç dörtlük ve sonunda kafiyeli bir beyitle biter.'),
  ('Bir şiir 14 dizelidir; ilk sekiz dize abba abba, son altı dize cdc dcd biçiminde kafiyelidir. Bu şiir hangi nazım biçimine örnektir?', 'Petrarca tipi sone', ['Shakespeare tipi sone', 'Terzarima', 'Haiku'], 'Sekizlik ve altılık bölümlerden oluşan, abba abba ile başlayan 14 dizelik yapı Petrarca (İtalyan) sonesidir.'),
  ('Fransız edebiyatında üç bent ve kısa bir son bölümden (envoi) oluşan, her bendin aynı dizeyle (nakaratla) bittiği nazım biçimi hangisidir?', 'Balad', ['Sone', 'Haiku', 'Terzarima'], 'Fransız baladı genellikle üç bent ve bir sunuş bölümünden oluşur; bentler aynı nakarat dizesiyle biter.'),
  ('İngiliz edebiyatında aabba kafiye düzenli, beş dizelik, nükteli ve çoğu zaman saçma güldürüye dayanan kısa şiir biçimine ne ad verilir?', 'Limerick', ['Sone', 'Eleji', 'Haiku'], 'Limerick beş dizelik, aabba kafiyeli mizahi bir İngiliz şiir biçimidir.'),
  ('Şiirde sözcüklerin anlamından çok seslerinin ve çağrışımlarının öne çıkarılmasına dayanan anlayış hangi ilkeyle ifade edilebilir?', 'Saf (öz) şiir anlayışı', ['Toplumcu gerçekçi şiir anlayışı', 'Natüralizm', 'Tezli edebiyat'], 'Saf şiir, anlamı geri plana iterek musikiyi, sesi ve telkini öne çıkaran bir şiir anlayışıdır.'),
  ('Bir şiirde \'kırmızı bir çığlık\' ifadesinde bir duyuya ait niteliğin başka bir duyuya aktarılması hangi kavramla açıklanır?', 'Sinestezi', ['Asonans', 'Kafiye', 'Nakarat'], 'Renk (görme duyusu) ile çığlık (işitme duyusu) bir araya getirilmiştir; bu duyular arası aktarım sinestezidir.'),
  ('\'Şiir, sözcüklerle resim yapma sanatıdır.\' görüşünü en güçlü biçimde destekleyen şiir özelliği hangisidir?', 'Görsel imgelerin zengin kurulması', ['Dizelerin hece sayılarının eşit olması', 'Kafiyelerin yalnızca çapraz düzende olması', 'Şiirin bir başlık taşıması'], 'Şiiri resme yaklaştıran, okurun zihninde görüntü oluşturan imgeler ve betimlemelerdir.'),
  ('\'Çocuk, ceylan gibi sekerek koştu.\' cümlesinde teşbihin unsurlarından kaç tanesi kullanılmıştır?', 'Dört', ['Üç', 'İki', 'Bir'], 'Benzeyen \'çocuk\', benzetilen \'ceylan\', edat \'gibi\', yön \'sekerek koşma\'dır; dört unsur da kullanılmıştır.'),
  ('Kapalı istiare ile teşhis arasındaki ilişki için aşağıdakilerden hangisi doğrudur?', 'İnsana benzetmeli kapalı istiare teşhis de içerir', ['Teşhis yalnız açık istiarede bulunur', 'Kapalı istiare yalnızca hayvanlara benzetmeyle yapılır', 'İkisi birbirini kesinlikle dışlayan sanatlardır'], 'İnsan dışı bir varlığa insan özelliği verildiğinde, benzetilen insan söylenmediği için kapalı istiare ve teşhis birlikte bulunur.'),
  ('\'Gökyüzünün gözyaşları toprağı serinletti.\' cümlesinde \'gözyaşları\' sözüyle hangi varlık kastedilmektedir ve bu kullanım hangi sanata örnektir?', 'Yağmur kastedilmiş; açık istiare yapılmıştır', ['Bulut kastedilmiş; teşbih-i beliğ yapılmıştır', 'Güneş kastedilmiş; mübalağa yapılmıştır', 'Rüzgâr kastedilmiş; mecazımürsel yapılmıştır'], 'Benzeyen \'yağmur\' söylenmemiş, yalnız kendisine benzetilen \'gözyaşı\' söylenmiştir; bu açık istiaredir. Gökyüzüne insan gibi gözyaşı verilmesi ayrıca teşhis içerir.'),
  ('\'Geceleri şehrin yıldızları sokak lambalarıydı.\' cümlesindeki benzetme türü hangisidir?', 'Teşbih-i beliğ', ['Açık istiare', 'Kapalı istiare', 'Tecahülüarif'], 'Benzeyen (sokak lambaları) ve kendisine benzetilen (yıldızlar) birlikte söylenmiş, edat ve yön kullanılmamıştır.'),
  ('Kinaye ile tevriye arasındaki fark nedir?', 'Kinayede mecaz anlam, tevriyede uzak anlam kastedilir', ['Kinayede iki sözcük karşıt anlamlıdır, tevriyede eş anlamlıdır', 'Tevriye yalnız sesteş sözcüklerle değil, deyimlerle yapılır', 'Kinaye ünlü bir olaya, tevriye bir atasözüne gönderme yapar'], 'İkisinde de bir söz iki anlamı düşündürür. Kinayede asıl kastedilen mecaz anlam, tevriyede ise sözcüğün akla ilk gelmeyen uzak anlamıdır.'),
  ('Türkçedeki deyimlerin önemli bir bölümünün kinayeli olmasının nedeni nedir?', 'Gerçek anlamlarının da düşünülebilmesi', ['Tümünün sesteş sözcüklerden oluşması', 'Ölçülü ve kafiyeli olmaları', 'Tarihî bir olaya gönderme yapmaları'], '\'Eli açık olmak\', \'ayağını sıcak tutmak\' gibi deyimlerde gerçek anlam da düşünülebilir, ama kastedilen mecaz anlamdır.'),
  ('Teşhis ile intak arasındaki ilişki hakkında aşağıdakilerden hangisi doğrudur?', 'Konuşturmada intakla birlikte teşhis de oluşur', ['Teşhis olan her cümlede intak da vardır', 'İntak yalnızca insanların konuşturulmasıdır', 'İkisi aynı cümlede hiçbir zaman bulunmaz'], 'Konuşmak insana özgü olduğundan intak, teşhisi de içerir; ancak her teşhiste konuşturma yoktur.'),
  ('Zıt anlamlı iki sözcüğün tek bir kavram içinde birleştirilmesiyle (örneğin \'sessiz çığlık\', \'tatlı acı\') oluşturulan anlatım biçimine Batı retoriğinde ne ad verilir?', 'Oksimoron', ['Aliterasyon', 'Metafor', 'Hiperbol'], 'Oksimoron, çelişik iki sözcüğün kaynaştırılarak yeni bir anlam üretilmesidir; tezatın yoğunlaştırılmış bir biçimidir.'),
  ('Bir anlatımın mübalağa sayılabilmesi için aşağıdakilerden hangisi gereklidir?', 'Söylenenin gerçekte o ölçüde olmaması', ['Cümlede mutlaka bir benzetme edatı bulunması', 'Bir tarihî olaya gönderme yapılması', 'Sözcüklerin karşıt anlamlı olması'], 'Mübalağada söz bilinçli olarak gerçeğin ötesine taşınır; benzetme ya da karşıtlık zorunlu değildir.'),
  ('Hüsnütalil ile tecahülüarif arasındaki temel fark nedir?', 'Hüsnütalilde neden uydurulur, tecahülüarifte bilmezlik vardır', ['Hüsnütalil yalnız soru, tecahülüarif yalnız emir cümlesiyle yapılır', 'Tecahülüarif doğa olaylarıyla, hüsnütalil tarihî olaylarla yapılır', 'İkisi de yalnız sesteş sözcüklere dayanır'], 'Hüsnütalilin özü gerçek dışı ama güzel bir gerekçe göstermek, tecahülüarifinki ise bilinen bir şeyi bilmiyormuş gibi davranmaktır.'),
  ('\'Yağmur, ayrılığımıza gökyüzü de ağladığı için yağıyordu.\' cümlesinde hüsnütalil ile birlikte hangi sanat da bulunmaktadır?', 'Teşhis', ['İrsalimesel', 'Tevriye', 'Leff ü neşr'], 'Yağmur, ayrılığa ağlamak gibi güzel bir nedene bağlanmıştır (hüsnütalil); gökyüzüne ağlama gibi insana özgü bir davranış da verilmiştir (teşhis).'),
  ('Tenasüp ile tezat arasındaki ortak ve farklı yön hangi seçenekte doğru verilmiştir?', 'İkisi anlam ilişkisine dayanır; tezatta ilişki karşıtlıktır', ['İkisi de sesteş sözcükle yapılır; tezat yalnız şiirde görülür', 'Tenasüpte sözcük tekrarlanır; tezatta hiç tekrar yoktur', 'İkisi de bir olaya gönderme yapar; tenasüp atasözüne dayanır'], 'Her iki sanat da anlam ilişkisi bulunan sözcüklere dayanır. Tenasüpte ilişki uyum, tezatta ise karşıtlık ilişkisidir.'),
  ('İrsalimesel ile telmihi birbirinden ayırmada en güvenilir ölçüt hangisidir?', 'İrsalimeselde atasözü, telmihte olay ya da öykü kullanılır', ['İrsalimesel soru biçiminde, telmih emir biçimindedir', 'Telmih yalnız manzum, irsalimesel yalnız nesir metinlerde görülür', 'İkisinde de sesteş sözcükler kullanılır'], 'Telmih bilinen bir olaya ya da hikâyeye gönderme yapar; irsalimesel ise düşünceyi kanıtlamak için atasözü ya da vecize getirir.'),
  ('Cinas ve tevriye sanatlarını sürekli karıştıran bir öğrenciye öğretmeninin yapacağı en doğru açıklama hangisidir?', 'Cinasta sesteş sözcük yinelenir, tevriyede tek sözcük iki anlamlıdır', ['Cinas karşıt, tevriye uyumlu kavramlarla yapılır', 'Tevriye yalnızca atasözlerinde bulunur', 'Cinas bir olaya, tevriye bir kişiye gönderme yapar'], 'Cinasta aynı ses değerli sözcükler farklı anlamlarla yan yana kullanılır; tevriyede ise tek bir sözcük hem yakın hem uzak anlamı çağrıştırır.'),
  ('Cinaslı kafiye ile cinas sanatı arasındaki ilişki için hangisi doğrudur?', 'Cinasın dize sonunda kafiye olarak kullanılmasıdır', ['Cinaslı kafiye yalnız düz yazıda, cinas yalnız şiirde görülür', 'İkisi tamamen ilgisiz kavramlardır', 'Cinas kafiyeden, cinaslı kafiye ise rediften doğar'], 'Sesteş sözcükler dize sonlarında kafiye oluşturduğunda cinaslı kafiye ortaya çıkar; bu, cinas sanatının kafiyede kullanılmasıdır.'),
  ('Tecahülüarif ile istifham arasındaki fark hangisidir?', 'Tecahülüarifte bilmezlikten gelinir, istifhamda gelinmez', ['İstifham yalnızca ünlemle, tecahülüarif yalnız emirle yapılır', 'Tecahülüarif bir atasözüne dayanır, istifham bir olaya', 'İstifham yalnız düz yazıda, tecahülüarif yalnız şiirde görülür'], 'İki sanat da soru biçimini kullanabilir; ama tecahülüarifte bilinen bir gerçek bilinmiyormuş gibi sunulur, istifhamda böyle bir bilmezlik yoktur.'),
  ('Bir şiirde önce birkaç sözcük sıralanıp sonra bunlarla ilgili başka sözcüklerin aynı ya da farklı sırayla verilmesine ne ad verilir?', 'Leff ü neşr', ['Tenasüp', 'Tekrir', 'Tezat'], 'Leff ü neşr (toplayıp yayma), ilk dizede sayılan ögelerle ilgili ögelerin ikinci dizede sırayla ya da karışık olarak verilmesidir.'),
  ('\'Yüzün, saçın, boyun; güneş, gece, fidan.\' sözünde ilk üç sözcükle son üç sözcük arasındaki sıralı ilişki hangi sanatı oluşturur?', 'Leff ü neşr', ['Tenasüp', 'Cinas', 'İstifham'], 'Yüz güneşe, saç geceye, boy fidana karşılık gelecek biçimde sıralanmıştır; bu leff ü neşrdir.'),
  ('Şairin kendi kendine, başka biriymiş gibi seslenerek konuşmasına ne ad verilir?', 'Tecrit', ['Tariz', 'Nida', 'İntak'], 'Tecrit, şairin kendisini soyutlayıp karşısına koyarak kendine seslenmesidir.'),
  ('\'Ey gönül, sen de mi yoruldun bu yollarda?\' dizesinde şairin kendi gönlüne başka biriymiş gibi seslenmesi en çok hangi sanata yakındır?', 'Tecrit', ['Telmih', 'Tevriye', 'Leff ü neşr'], 'Şair kendi iç varlığını karşısına alıp ona seslenmektedir; bu tecrittir. \'Ey\' ile nida da bulunur.'),
  ('İroni ile tariz arasındaki ilişki için hangisi doğrudur?', 'Tersini kastetmeye dayanır ve tarizle örtüşür', ['İroni yalnızca karşıt sözcüklerle yapılır', 'Tariz bir olaya, ironi bir atasözüne gönderme yapar', 'İroni bir ölçü türüdür, tariz bir kafiye türüdür'], 'Batı retoriğindeki ironi, alaycı biçimde tersini kastetmedir; geleneksel terim olarak tariz bu anlatımı karşılar.'),
  ('Bir anlatıcının olayları kahramanın göremediği bir gerçeği okurla paylaşarak aktarması, böylece kahramanın sözlerinin okur için farklı bir anlam kazanmasına ne ad verilir?', 'Dramatik ironi', ['Aliterasyon', 'Tecrit', 'Hüsnütalil'], 'Dramatik ironide okur ya da seyirci, kahramanın bilmediği bir şeyi bilir; bu yüzden kahramanın sözleri ikinci bir anlam kazanır.'),
  ('Bir metnin \'durgun\' bir anlatıma sahip olduğu söyleniyorsa, bu metinde hangi anlatım biçiminin baskın olması beklenir?', 'Betimleme', ['Öyküleme', 'Tartışma', 'Diyalog'], 'Betimlemede zaman ilerlemez, eylem yoktur; görüntü sabitlenmiş gibidir. Bu yüzden betimleme durgun bir anlatım üretir.'),
  ('Bir yazar, betimlemelerinde yalnızca görme duyusuna değil; koku, ses ve dokunma izlenimlerine de yer veriyor. Bu tercih betimlemeye en çok ne kazandırır?', 'Çok yönlü bir canlılık', ['Bilimsel ve ölçülebilir bir kesinlik', 'Kronolojik bir düzen', 'Tartışmacı bir hava'], 'Farklı duyulara seslenen ayrıntılar okurun anlatılanı daha bütünlüklü yaşamasını sağlar.'),
  ('Bir metin parçasında hem bilgi verme hem de karşıt bir görüşü çürütme amacı bulunuyorsa, parçanın baskın anlatım biçimi neye göre belirlenmelidir?', 'Parçanın asıl amacına göre', ['Parçadaki cümle sayısının tek ya da çift olmasına göre', 'Parçada kullanılan sıfatların sayısına göre', 'Parçanın hangi kitapta yer aldığına göre'], 'Anlatım biçimi metnin amacıyla belirlenir: okuru ikna etmek asıl amaçsa tartışmacı, bilgilendirmek asıl amaçsa açıklayıcı anlatım baskın sayılır.'),
  ('Karşılaştırma ile benzetme arasındaki temel fark nedir?', 'Karşılaştırma farkları da gösterir, benzetme yalnız benzerlik kurar', ['Benzetmede sayısal veri kullanılır, karşılaştırmada kullanılmaz', 'Karşılaştırma yalnız şiirde, benzetme yalnız düz yazıda bulunur', 'Benzetme yalnızca tanınmış kişilerin sözlerine dayanır'], 'Benzetme, bir şeyi daha iyi anlatmak için güçlü bir yönden ona benzeyen bir şeyle ilişkilendirir; karşılaştırmada ise farklılıklar da ele alınır.'),
  ('Aşağıdaki cümlelerden hangisinde birden çok düşünceyi geliştirme yolu bir arada kullanılmıştır?', 'Deneme kişiseldir; örneğin bir yürüyüşten yola çıkabilir.', ['Roman, geniş olay örgüsüne sahip bir anlatı türüdür.', 'Kitaplar bir dost gibidir.', 'Okulumuzda 300 öğrenci okuyor.'], 'İlk cümlede önce deneme tanımlanmış, ardından bir örnekle açıklanmıştır. Diğerlerinde yalnız tanımlama, benzetme ve sayısal veri vardır.'),
  ('Bir yazar, iddiasını desteklemek için yalnızca kendi kişisel deneyimine dayanan tek bir örnek veriyorsa bu yaklaşımın en önemli zayıflığı nedir?', 'Genelleme için yetersiz kalması', ['Dilin gereğinden fazla süslü ve mecazlı olması', 'Tanımlamanın eksik olması', 'Metnin manzum olmaması'], 'Tek ve kişisel bir örnek, genel bir yargıyı kanıtlamaya yetmez; güçlü bir tartışmada çok sayıda ve nesnel kanıt gerekir.'),
  ('Bir öğrencinin \'İklim değişikliği tarımı etkiler\' iddiasını en güçlü biçimde destekleyecek kanıt aşağıdakilerden hangisidir?', 'Son elli yılın rekolte ve sıcaklık verileri', ['Komşusunun bahçesindeki domateslerin küçülmesi', 'Bir şairin yağmur üzerine yazdığı dize', 'Ünlü bir şarkıcının iklim hakkındaki sosyal medya paylaşımı'], 'Uzun dönemli ve ölçülebilir veriler, nesnel ve güvenilir bir kanıt sunar; diğerleri kişisel, edebî ya da yetkin olmayan kaynaklardır.'),
  ('Bir öykünün yazarı ile anlatıcısı arasındaki ilişki için aşağıdakilerden hangisi doğrudur?', 'Anlatıcı yazarın kurduğu kurmaca bir sestir', ['Anlatıcı her zaman yazarın kendisidir', 'Anlatıcı yalnızca biyografilerde bulunur', 'Yazar ve anlatıcı aynı anda konuşamaz'], 'Kurmaca metinlerde anlatıcı yazarın yarattığı bir kurmaca varlıktır; \'ben\' diye konuşan anlatıcı bile yazarla özdeş değildir.'),
  ('Bir yazar, okurdan bazı bilgileri saklayarak merakı sürekli canlı tutmak istiyor. Hangi bakış açısını seçmesi bu amaca daha uygun düşer?', 'Gözlemci bakış açısı', ['İlahi bakış açısı', 'Her bölümde iç sesin verildiği anlatım', 'Geleceği önceden haber veren anlatıcı'], 'Gözlemci anlatıcı kişilerin düşüncelerini bilmediği için okur da yalnızca dış davranışları görür; bu, merakı korumaya elverişlidir.'),
  ('Anlatıcının olayları aktarırken araya girip okura doğrudan seslendiği, \'Sevgili okur, şimdi size kahramanımızın gizli yüzünü anlatacağım.\' gibi müdahalelerine ne ad verilir?', 'Anlatıcı müdahalesi', ['Bilinç akışı', 'İç monolog', 'Gözlemci anlatım'], 'Anlatıcının olay akışını kesip okura seslenmesi ya da yorum yapması anlatıcı müdahalesidir; özellikle 19. yüzyıl romanlarında sık görülür.'),
  ('Güvenilmez anlatıcı kavramı neyi ifade eder?', 'Aktardıklarından şüphe edilen anlatıcıyı', ['Her şeyi bilen tanrısal anlatıcıyı', 'Olayları yalnız kamera gibi aktaran anlatıcıyı', 'Mektuplarla konuşan çoklu anlatıcıları'], 'Güvenilmez anlatıcı; yanılgı, çıkar ya da ruh hâli nedeniyle olayları çarpıtan anlatıcıdır. Okur, aktarılanları sorgulamak zorunda kalır.'),
  ('Bir öğrenci, bir öyküyü kahraman bakış açısından ilahi bakış açısına dönüştürmek istiyor. Hangi değişikliği yapması gerekir?', 'Üçüncü kişiye geçip herkesin iç dünyasını vermek', ['Öyküdeki bütün diyalogları silmek', 'Anlatımı ikinci kişiye çevirmek', 'Öyküyü manzum biçimde yeniden yazmak'], 'İlahi bakış genellikle üçüncü kişi ağzıyla kurulur ve anlatıcı tüm kişilerin düşüncelerine erişir.'),
  ('Bilinç akışı ile iç monolog arasındaki temel fark hangisidir?', 'Bilinç akışı dağınık çağrışımlara, iç monolog düzenli iç konuşmaya dayanır', ['İç monolog yalnızca tiyatroda, bilinç akışı yalnızca şiirde kullanılır', 'Bilinç akışı bir gözlemci anlatıcıyla, iç monolog ilahi anlatıcıyla kurulur', 'İkisi de kişilerin karşılıklı konuşmasıdır'], 'İki teknik de kişinin iç dünyasını verir. Bilinç akışı düşüncelerin ham ve kopuk hâlini, iç monolog ise kişinin kendine yönelttiği düzenli konuşmayı yansıtır.'),
  ('Bir romanda yazarın romanın nasıl yazıldığını, kurgunun kendisini anlatı içinde tartışmasına ne ad verilir?', 'Üstkurmaca', ['Leitmotiv', 'Montaj', 'İç monolog'], 'Üstkurmaca (metafiction), kurmacanın bir kurmaca olduğunu okura hissettiren, yazma sürecini metne katan tekniktir.'),
  ('Bir romanda, kahraman da bir roman yazıyor ve okur, romanın içindeki romanın bölümlerini de okuyor. Bu yapı hangi anlatım anlayışına örnektir?', 'Üstkurmaca', ['Natüralist anlatım', 'Gözlemci anlatım', 'Kronolojik anlatım'], 'Romanın içinde bir başka romanın yazılması ve kurmaca sürecin görünür kılınması üstkurmacanın tipik bir örneğidir.'),
  ('Bir metnin başka metinlerle (alıntı, gönderme, parodi yoluyla) kurduğu ilişkiye ne ad verilir?', 'Metinlerarasılık', ['Bilinç akışı', 'Geriye dönüş', 'İç monolog'], 'Metinlerarasılık, bir metnin önceki metinlerden izler taşıması ya da onlarla diyalog kurmasıdır.'),
  ('Parodi ile pastiş arasındaki fark nedir?', 'Parodi alaycıdır, pastiş saygılı bir öykünmedir', ['Parodi kurmaca, pastiş belgeseldir', 'Pastiş yalnız şiirde, parodi yalnız romanda görülür', 'İkisi de mektup biçiminde yazılır'], 'İki teknik de taklide dayanır; parodi alay ve eleştiri içerir, pastiş ise genellikle saygı ya da oyun amacıyla yapılan öykünmedir.'),
  ('Bir romanda olayların sırasıyla değil de sonundan başlanıp geriye doğru ya da parçalı biçimde verilmesi anlatıya en çok ne kazandırır?', 'Okurun parçaları birleştirmesini', ['Olayların masal havasında anlatılmasını', 'Metnin ölçülü ve kafiyeli olmasını', 'Anlatıcının ortadan kalkmasını'], 'Kronolojinin kırılması okuru etkin kılar; okur parçaları zihninde birleştirerek bütüne ulaşır.'),
  ('Bir öyküde iki farklı zamanda ya da yerde geçen olayların bölümler hâlinde dönüşümlü olarak verilmesi hangi kavramla açıklanır?', 'Paralel kurgu', ['Leitmotiv', 'İç monolog', 'Tecrit'], 'Paralel (koşut) kurguda iki ayrı olay dizisi birbirini izleyen bölümlerde dönüşümlü anlatılır.'),
  ('Bir anlatıda ileride olacak bir olayın önceden sezdirilmesine, ipucu verilmesine ne ad verilir?', 'Prolepsis', ['Geriye dönüş', 'Bilinç akışı', 'İç monolog'], 'Prolepsis, gelecekte yaşanacak bir olayın önceden haber verilmesi ya da sezdirilmesidir; geriye dönüşün (analepsis) tersidir.'),
  ('Anlatıdaki olayların yaşandığı sürenin, o olayları anlatmak için harcanan metin uzunluğundan farklı olabilmesi hangi kavramlarla açıklanır?', 'Olay zamanı ve anlatma zamanı', ['Kafiye ve redif düzeni', 'Tema ve konu', 'Serim ve düğüm'], 'Olay zamanı olayların gerçekte sürdüğü zamandır; anlatma zamanı ise bu olayların metinde anlatılmasına ayrılan süredir. Birkaç yıl tek bir cümleyle geçilebilir.'),
  ('Bir romanda mekânın yalnızca bir dekor olmaktan çıkıp kişilerin ruh hâlini ve kaderini etkileyen bir unsur hâline gelmesi neyi gösterir?', 'Mekânın işlevsel kullanıldığını', ['Romanın şiirle yazıldığını', 'Bakış açısının gözlemci olduğunu', 'Olayların kronolojik verildiğini'], 'Mekân, kişilerin duygu ve davranışlarını biçimlendiriyorsa yalnız fon değil, anlatının işlevsel bir öğesidir.'),
  ('Bir öyküde kahramanın ve okurun beklentisinin tersine dönen ani bir değişime (örneğin kurtarıcı sanılan kişinin hain çıkması) Aristoteles\'in terimleriyle ne ad verilir?', 'Peripeteia', ['Katarsis', 'Koro', 'Hamartia'], 'Peripeteia, olayların beklenmedik biçimde tersine dönmesidir; trajedinin temel öğelerinden biridir.'),
  ('Anlatı sanatında \'sahne\' ile \'özet\' arasındaki fark nedir?', 'Sahne ayrıntılı ve anlık, özet hızlı ve topludur', ['Sahne yalnız tiyatroda, özet yalnız şiirde bulunur', 'Özet diyaloglardan, sahne yalnız betimlemelerden oluşur', 'Sahne her zaman geçmişi, özet her zaman geleceği anlatır'], 'Sahnede olay zamanı ile anlatma zamanı birbirine yaklaşır, diyaloglar yer alır; özette ise uzun süreler kısaca geçilir.'),
  ('Olay örgüsünde olayların birbirine \'ve sonra\' bağıyla değil \'bu yüzden\' bağıyla bağlanmasının önemi nedir?', 'Kurguyu inandırıcı kılar', ['Olayları birbirinden bağımsız kılar', 'Metni şiire dönüştürür', 'Anlatıcının kimliğini gizler'], 'İyi bir olay örgüsünde olaylar birbirinin sonucu olarak gelişir; bu neden-sonuç zinciri kurguya mantık ve inandırıcılık kazandırır.'),
  ('Bir metinde birden çok dil işlevi bir arada bulunabilir. Bu durumda metnin türü belirlenirken neye bakılır?', 'Baskın olan işleve', ['En son cümledeki işleve', 'Başlıktaki işleve', 'En kısa cümledeki işleve'], 'Metinlerde birden çok işlev bulunabilir; türü belirleyen, metnin genelinde öne çıkan baskın işlevdir.'),
  ('Bir şiirde şairin \'Ey okur, sen de bir gün bu yollardan geçeceksin!\' demesi aşağıdakilerden hangisini gösterir?', 'Şiirde alıcıya yönelik işlev de bulunabileceğini', ['Şiirin mutlaka öğretici olduğunu', 'Şiirde şiirsel işlevin hiç olmadığını', 'Metnin bir haber olduğunu'], 'Şiirde baskın işlev şiirseldir; ama okura seslenme gibi alıcıya yönelik işlevler de yan işlev olarak yer alabilir.'),
  ('Aristoteles\'in sanatın gerçekliği taklit ederek yeniden üretmesi anlamında kullandığı kavram hangisidir?', 'Mimesis', ['Katarsis', 'Hamartia', 'Peripeteia'], 'Mimesis (yansıtma, taklit), Aristoteles\'e göre sanatın temelidir; sanat gerçekliği olduğu gibi değil, olabilecek biçimde yansıtır.'),
  ('Olağanüstü olayların gerçekçi bir dünyanın içinde, kişiler tarafından doğal karşılanarak anlatıldığı anlatım biçimine ne ad verilir?', 'Büyülü gerçekçilik', ['Natüralizm', 'Klasisizm', 'Romantizm'], 'Büyülü gerçekçilikte olağanüstü olaylar sıradan gerçeklikle iç içe verilir ve kişiler bunları şaşırmadan karşılar.'),
  ('Bir öyküde ölmüş bir büyükannenin her akşam mutfağa gelip yemek yapması aile tarafından olağan karşılanıyorsa bu öyküde hangi anlatım anlayışı görülür?', 'Büyülü gerçekçilik', ['Gözlemci anlatım', 'Klasik trajedi', 'Belgesel anlatım'], 'Olağanüstü bir olayın gündelik ve doğal bir şeymiş gibi anlatılması büyülü gerçekçiliğin belirgin özelliğidir.'),
  ('Masal ile fantastik roman ortak olarak olağanüstülük içerir. Fantastik romanı masaldan ayıran özellik nedir?', 'Yazarı belli, ayrıntılı kurulmuş bir dünyası olması', ['Olağanüstü öğe içermemesi', 'Yalnızca sözlü gelenekte yaşaması', 'Kalıp döşeme sözleriyle başlaması'], 'Fantastik roman yazarın bilinçli olarak kurduğu, ayrıntılı bir dünya içerir; masal ise anonim ve kalıplaşmış bir sözlü anlatıdır.'),
  ('Alegori ile kurmaca arasındaki ilişkiyi en iyi açıklayan ifade hangisidir?', 'Alegoride olaylar ikinci bir anlamı simgeler', ['Alegori kurmaca olmayan bir türdür', 'Alegoride olaylar gerçek tarih belgelerinden alınır', 'Alegori yalnızca sayısal verilere dayanır'], 'Alegori, kurmaca bir anlatının ardında soyut ya da ahlaki bir anlam taşıdığı anlatımdır; fabllar bunun bilinen örnekleridir.'),
  ('\'Sen hiç yazın kar gördün mü? Ben gördüm: annemin saçlarında.\' cümlesinde \'kar\' sözcüğüyle ak saçlar kastedilmiştir. Bu kullanım hangi sanata örnektir?', 'Açık istiare', ['Teşbih-i beliğ', 'Hüsnütalil', 'Leff ü neşr'], 'Ak saçlar (benzeyen) söylenmemiş, yalnızca kar (benzetilen) söylenmiştir; bu açık istiaredir.'),
  ('\'Ey gece, kim demiş yalnız olduğunu? Bak, yıldızlar seninle uyanık.\' cümlesinde aşağıdaki sanatlardan hangisi yoktur?', 'Telmih', ['İstifham', 'Teşhis', 'Nida'], '\'Ey gece\' bir seslenmedir (nida); \'kim demiş...?\' yanıt beklemeyen bir sorudur (istifham); geceye seslenilmesi ve yıldızların uyanık olması kişileştirmedir (teşhis). Bilinen bir olaya gönderme (telmih) yoktur.'),
  ('\'Gece, kara pelerinini şehrin omuzlarına attı.\' cümlesinde hangi iki sanat bulunmaktadır?', 'Kapalı istiare ve teşhis', ['Telmih ve irsalimesel', 'Cinas ve tekrir', 'Tezat ve tevriye'], 'Gece insana benzetilmiş ama insan söylenmemiştir (kapalı istiare); geceye pelerin atma eylemi verilmesi kişileştirmedir (teşhis).'),
  ('\'Göklerden inen bu beyaz örtü, toprağı utancından mı saklıyor?\' dizesinde hangi sanatlar bir aradadır?', 'Açık istiare, istifham ve hüsnütalil', ['Telmih, tekrir ve cinas', 'Tezat, irsalimesel ve tevriye', 'Mecazımürsel, leff ü neşr ve tariz'], '\'Beyaz örtü\' ile kar kastedilmiştir (açık istiare); yanıt beklenmeyen bir soru vardır (istifham); kar yağışı utanç gibi şairane bir nedene bağlanmıştır (hüsnütalil).'),
  ('İnsan varoluşunun anlamsızlığını, mantıksız diyaloglar ve döngüsel olaylarla sahneye taşıyan modern tiyatro anlayışına ne ad verilir?', 'Absürt tiyatro', ['Klasik trajedi', 'Melodram', 'Töre komedisi'], 'Absürt (uyumsuz) tiyatro, iletişimsizliği ve anlam yoksunluğunu mantık dışı diyalog ve durumlarla gösterir.'),
  ('Seyircinin oyuna duygusal olarak kapılmasını engelleyip eleştirel düşünmesini sağlamaya çalışan, oyuncuların zaman zaman doğrudan seyirciye seslendiği tiyatro anlayışına ne ad verilir?', 'Epik tiyatro', ['Klasik trajedi', 'Vodvil', 'Melodram'], 'Epik tiyatro, \'yabancılaştırma\' yoluyla seyircinin olaylara mesafeli ve eleştirel bakmasını amaçlar.'),
  ('Bir tiyatro oyununu okumakla izlemek arasındaki farkı en iyi açıklayan yargı hangisidir?', 'Tiyatro metni sahnede oyuncu, ışık ve dekorla tamamlanır', ['Tiyatro metni okunduğunda kurmaca olmaktan çıkar', 'Oyun izlenirken diyaloglar ortadan kalkar', 'Okurken bütün sahne yönergeleri seyirciye söylenir'], 'Tiyatro metni sahnelenmek için yazılır; metin oyunculuk, dekor ve ışık gibi sahne ögeleriyle bütünlenir.'),
  ('Masal ile efsaneyi ayıran en önemli fark nedir?', 'Efsane gerçekmiş gibi inanılarak anlatılır', ['Masalda hiç olağanüstü öğe bulunmaz', 'Efsane yalnızca hayvanları konu alır', 'Masal yalnızca manzum yazılır'], 'Masalın gerçek olmadığı anlatıcı ve dinleyici tarafından bilinir; efsane ise gerçekten yaşanmış gibi anlatılır ve belli yer ya da kişilere bağlanır.'),
  ('Mensur şiir ile manzum hikâye karşılaştırıldığında hangisi doğrudur?', 'Mensur şiir nesir biçimli şiir, manzum hikâye şiir biçimli öyküdür', ['İkisi de ölçülü ve kafiyeli düz yazıdır', 'Mensur şiir olay anlatır, manzum hikâye duygu anlatır', 'Manzum hikâye yalnızca tiyatroda sahnelenir'], 'Mensur şiirde biçim düz yazı, öz şiirseldir; manzum hikâyede biçim şiir, öz ise öyküdür.'),
  ('Şiir ile manzume arasındaki ayrım için aşağıdakilerden hangisi doğrudur?', 'Manzume şiirsel derinlik taşımayabilir', ['Manzume her zaman serbest ölçüyle yazılır', 'Şiir yalnızca kafiyesiz olabilir', 'Manzume bir tiyatro türüdür'], 'Ölçü ve kafiye tek başına bir metni şiir yapmaz; duygu, imge ve sanat değeri taşımayan ölçülü metinler manzume olarak adlandırılır.'),
  ('Bir metinde hem kurmaca hem de gerçek olaylara dayanma özelliği arandığında aşağıdaki türlerden hangisi en sorunlu sınıflandırmaya yol açar?', 'Tarihî roman', ['Makale', 'Haber', 'Ansiklopedi maddesi'], 'Tarihî roman gerçek olay ve kişileri işler ama yine de kurmacadır; bu iki yönlülüğü nedeniyle sınıflandırmada tartışma doğurabilir.'),
  ('Bir parçada yazar, ünlü bir bilim insanının çalışmalarını yerinde görmek için laboratuvarına gidiyor, çalışanlarla konuşuyor ve izlenimlerini aktarıyor. Bu parçanın türü en çok hangisine uyar?', 'Röportaj', ['Mülakat', 'Biyografi', 'Deneme'], 'Yerinde gözlem, farklı kişilerle görüşme ve izlenimlerin birleştirilmesi röportajı tanımlar.'),
  ('\'Gün ışığı vurdu dağın başına\' dizesi 11 hecelidir. Bu dizeye durak bir sözcüğü bölmeyecek biçimde yerleştirildiğinde hangi yapı elde edilir?', '6+5', ['7+4', '5+6', '3+8'], '\'Gün ışığı vurdu\' 6, \'dağın başına\' 5 hecedir; 6+5 durağı hiçbir sözcüğü bölmez. 7+4 durağı \'dağın\', 5+6 durağı \'vurdu\', 3+8 durağı \'ışığı\' sözcüğünü böler.'),
  ('7\'li hece ölçüsüyle yazılmış bir dizenin en yaygın durak biçimi hangisidir?', '4+3', ['2+5', '1+6', '6+1'], '7\'li ölçüde dizeler genellikle 4+3 ya da 3+4 duraklı olur.'),
  ('Bir şiir hem kahramanlık olaylarını anlatıyor hem de şairin bu kahramanlar karşısındaki coşkulu duygularını dile getiriyorsa bu şiir için en doğru değerlendirme hangisidir?', 'Epik ağır basar ama lirik öğe de taşır', ['Yalnızca didaktik bir şiirdir', 'Pastoral şiirin tipik bir örneğidir', 'Dramatik şiirin kesin bir örneğidir'], 'Şiir türleri kesin sınırlarla ayrılmaz; kahramanlık anlatısı epik, coşkulu duygu anlatımı lirik özellik taşır.'),
  ('Bir romanda bir kasabanın tüm sakinleri ve onların karmaşık ilişkileri anlatılıyor; tek bir baş kahraman yok. Bu romanın kişi yapısı için en uygun değerlendirme hangisidir?', 'Kahraman yerine topluluğun merkeze alındığı bir yapı', ['Tek kişilik bir iç monolog romanı', 'Yalnızca hayvanların konuşturulduğu bir fabl', 'Mektuplardan oluşan bir epistolar roman'], 'Kişi kadrosunun geniş olması ve tek bir merkezî kahraman bulunmaması topluluğu öne çıkaran bir anlatı kurgusunu gösterir.'),
  ('Bir öyküde kahramanın yaşadığı küçük bir olay, okurda insanlık durumuna dair genel bir farkındalık uyandırıyor. Bu durum öykünün hangi niteliğine işaret eder?', 'Evrensellik', ['Kronolojiklik', 'Belgesellik', 'Göndergesellik'], 'Sıradan bir olay aracılığıyla bütün insanları ilgilendiren bir anlam üretmek, edebî metnin evrensel boyutunu gösterir.'),
  ('\'Kalemim ağlıyor bu satırları yazarken.\' cümlesindeki kalemin ağlaması hangi sanatlarla açıklanır?', 'Teşhis ve kapalı istiare', ['Telmih ve irsalimesel', 'Cinas ve tevriye', 'Leff ü neşr ve tecrit'], 'Kalem insana benzetilmiş ama insan söylenmemiş (kapalı istiare); kaleme ağlama gibi insana özgü bir eylem verilmiştir (teşhis).'),
  ('Aşağıdakilerden hangisinde soru biçimi tecahülüarif sanatı için değil, yalnızca anlatımı etkili kılmak için kullanılmıştır?', 'Kim unutabilir o kara günleri?', ['Bu senin sesin mi, yoksa bir kuşun mu?', 'Gökte yıldız mı kaydı, yoksa sen mi gülümsedin?', 'Bu ay mı, yoksa senin yüzün mü?'], 'İlk seçenekte bilmezlikten gelme yoktur; cevap beklenmeyen etkili bir soru (istifham) vardır. Diğerlerinde bilinen bir şey bilinmiyormuş gibi sorulmuştur.'),
  ('\'Okul bugün bayram yerine döndü.\' cümlesinde aşağıdakilerden hangisi vardır?', 'Mecazımürsel', ['Tecahülüarif', 'Leff ü neşr', 'İrsalimesel'], 'Bayram yerine dönen okulun binası değil, oradaki öğrenciler ve öğretmenlerdir; yer söylenip oradakiler kastedilmiştir. \'Bayram yerine dönmek\' aynı zamanda benzetmeye dayalı bir deyimdir.'),
  ('Bir denemede konunun çok farklı yönlerine dağınık biçimde değinilmesi ve kesin bir sonuca bağlanmaması nasıl değerlendirilmelidir?', 'Türün doğasına uygun bir özellik olarak', ['Türün kurallarına aykırı bir kusur olarak', 'Makaleye özgü bir özellik olarak', 'Bilimsel bir yöntem hatası olarak'], 'Deneme kesin sonuçlara ulaşma zorunluluğu taşımaz; serbest düşünce gezintisi türün doğasıdır.'),
  ('Bir anı yazarının, aynı olayı anlatan başka tanıkların anlatımıyla çelişen ayrıntılar vermesi en çok neyle açıklanabilir?', 'Anının öznel ve hafızaya dayalı olmasıyla', ['Anının kurmaca bir tür olmasıyla', 'Anının yalnız şiirle yazılmasıyla', 'Anının bilimsel deneylere dayanmasıyla'], 'Anı yazarı olayları kendi bakışından ve hafızasından aktarır; bu yüzden ayrıntılar başka tanıklarla farklılık gösterebilir.'),
  ('Biyografi yazarının hayatını anlattığı kişiye büyük hayranlık duyması hangi riski doğurur?', 'Kişinin olumsuz yönlerinin gizlenmesi', ['Metnin şiire dönüşmesi', 'Olayların masallaşması', 'Metnin kısalması'], 'Hayranlık, yazarın nesnelliğini zayıflatıp kişiyi yalnızca olumlu yönleriyle anlatmasına yol açabilir.'),
  ('\'Yaz\' sözcüğünün bir dizede mevsim, diğer dizede \'yazmak\' anlamında kullanıldığı iki dize sonunu inceleyen öğrenci \'Burada redif var.\' diyor. Öğrencinin hatası nedir?', 'Görev ve anlamı farklı sözcüğü redif sanması', ['Kafiyeyi dize başında araması', 'Hece sayısını yanlış sayması', 'Ölçüyü aruz sanması'], 'Redif için aynı görev ve anlam gerekir; anlamları farklı sesteş sözcükler cinaslı kafiye oluşturur.'),
  ('\'Yanar / Kanar\' sözcükleriyle biten iki dizede redif ve kafiye doğru olarak hangi seçenekte verilmiştir?', 'Redif: -ar; kafiye: an (tam)', ['Redif: -nar; kafiye: a (yarım)', 'Redif yok; kafiye: anar (zengin)', 'Redif: -anar; kafiye yok (yalnız redif)'], 'Geniş zaman eki \'-ar\' iki sözcükte aynı görevde olduğu için rediftir. Kalan \'yan\' ve \'kan\' köklerinde \'an\' iki ses ortaktır; bu tam kafiyedir.'),
  ('Bir romanda her bölüm farklı bir kişinin iç sesiyle anlatılıyor ve okur aynı olayı farklı gözlerden okuyor. Bu tercihin okura etkisi nedir?', 'Olayı çok yönlü değerlendirmesi', ['Olayın tek doğrusunu öğrenmesi', 'Anlatıcıyı hiç fark etmemesi', 'Metni şiir olarak okuması'], 'Çoğul anlatıcı ve iç ses, okurun tek bir bakışa bağlı kalmadan olayı farklı açılardan yorumlamasını sağlar.'),
  ('Bir anlatıda olayları kahramanın çocukluk yıllarında yaşadıklarını yetişkin olduğunda anlatan bir anlatıcı aktarıyor. Bu durumda anlatıcının iki \'ben\'i arasındaki fark ne yaratabilir?', 'Olayların yetişkin bakışıyla yeniden yorumlanması', ['Olayların hiçbir zaman anlatılamaması', 'Metnin tiyatroya dönüşmesi', 'Anlatıcının gözlemci konuma geçmesi'], 'Yetişkin anlatıcı, çocukken yaşadıklarını o günkü bilgisinin ötesinde değerlendirebilir; bu da anlatıya ironi ve derinlik katar.'),
  ('Masal kahramanlarının çoğunlukla \'padişahın küçük oğlu\', \'keloğlan\', \'üç kız kardeş\' gibi adsız ya da tip niteliğinde olması neyi gösterir?', 'Masalın bireyi değil türü temsil ettiğini', ['Masalların tarihî belge olduğunu', 'Kahramanların gerçek kişiler olduğunu', 'Masalın yazarlarının belli olduğunu'], 'Masal kahramanları bireysel derinlik taşımaz; iyilik, kötülük, kurnazlık gibi nitelikleri temsil eden tiplerdir.'),
  ('Panel ile sempozyum arasındaki fark nedir?', 'Sempozyum daha bilimsel ve bildiriye dayalıdır', ['Panelde hiç konuşmacı olmaz', 'Sempozyum yalnızca iki kişi arasında yapılır', 'Panel yalnızca yazılı olarak yapılır'], 'Panel bir konunun uzmanlarca dinleyici önünde tartışıldığı tek oturumluk toplantıdır; sempozyum ise bildirilerin sunulduğu, günlerce sürebilen bilimsel bir etkinliktir.'),
  ('Bir şiirde \'kapı\' imgesinin yeniden ve yeniden kullanılıp bazen umut, bazen ayrılık anlamı kazanması şiir dilinin hangi özelliğini gösterir?', 'Sözcüğe çok katmanlı anlam yüklenebilmesi', ['Sözcüklerin yalnız sözlük anlamıyla kullanılması', 'Şiirin bilimsel bir dille yazılması', 'Kafiyenin dize başlarında bulunması'], 'Şiirde aynı imge farklı bağlamlarda farklı anlamlar kazanabilir; bu, şiir dilinin çağrışım zenginliğini gösterir.'),
  ('Klasik trajedide kahramanın kendi gerçek durumunu ya da kimliğini geç de olsa fark ettiği ana Aristoteles\'in Poetika\'sında ne ad verilir?', 'Anagnorisis (tanıma)', ['Katarsis (ruhsal arınma)', 'Hamartia (trajik kusur)', 'Mimesis (yansıtma, taklit)'], 'Anagnorisis, kahramanın bilmediği bir gerçeği tanıdığı andır; çoğu zaman peripeteia ile birlikte gelir.'),
  ('Destanların sözlü gelenekte yayılırken farklı bölgelerde farklı biçimler (varyantlar) kazanmasının nedeni nedir?', 'Anlatıcıların anlatıyı yeniden kurması', ['Destanların tek bir yazarca yazılması', 'Destanların hiç anlatılmaması', 'Destanların yalnızca taşlara kazınması'], 'Sözlü gelenekte her anlatıcı metni hafızasından ve kendi üslubuyla yeniden söyler; bu da varyantların doğmasına yol açar.'),
  ('Bir yazarın \'Bu öykü gerçek bir olaydan esinlenmiştir.\' notunu düşmesi öykünün türü bakımından neyi değiştirir?', 'Hiçbir şeyi; öykü kurmaca olarak kalır', ['Öyküyü biyografiye dönüştürür', 'Öyküyü bir habere dönüştürür', 'Öyküyü bir tarih belgesi yapar'], 'Gerçek bir olaydan esinlenmek kurmacayı ortadan kaldırmaz; olay yazarın kurgusu içinde yeniden yaratılmıştır.'),
  ('Bir trajedide kahraman, kehanetten kaçmaya çalışırken farkında olmadan kehaneti gerçekleştiriyor. Bu durum hangi kavramı en iyi örnekler?', 'Trajik ironi', ['Fars', 'Vodvil', 'Pastiş'], 'Kahramanın kaçmak istediği sonu kendi eylemleriyle hazırlaması ve seyircinin bunu bilmesi trajik (dramatik) ironidir.'),
  ('Bir yazar bir kavramı açıklarken önce \'ne olmadığını\' sıralayıp ardından ne olduğunu söylüyor. Bu yöntem hangi düşünceyi geliştirme yolunun bir biçimidir?', 'Tanımlama', ['Tanık gösterme', 'Sayısal veri', 'Benzetme'], 'Bir kavramı ayırt ederek sınırlarını çizmek ve sonunda ne olduğunu söylemek, tanımlamanın bir uygulamasıdır.'),
];
